(async () => {
  const { existsSync } = await import('node:fs');
  const inputPath = process.env.INPUT_PATH;
  const outputPath = process.env.OUTPUT_PATH;
  if (!inputPath) throw new Error('Missing INPUT_PATH');
  if (!outputPath) throw new Error('Missing OUTPUT_PATH');
  if (!existsSync(inputPath)) throw new Error('Input file does not exist: ' + inputPath);
  globalThis.inputPath = inputPath;
  globalThis.outputPath = outputPath;
})();

(async () => {
  const { readFileSync } = await import('node:fs');
  const { parse } = await import('csv-parse');
  const inputPath = globalThis.inputPath;
  const content = readFileSync(inputPath, 'utf8');
  const records = await new Promise((resolve, reject) => {
    parse(content, { delimiter: '\t', columns: true, trim: true }, (err, output) => {
      if (err) reject(err);
      else resolve(output);
    });
  });
  globalThis.records = records;
})();

(async () => {
  const { writeFileSync } = await import('node:fs');
  const outputPath = globalThis.outputPath;
  const records = globalThis.records;
  writeFileSync(outputPath, JSON.stringify(records, null, 2), 'utf8');
  console.log(JSON.stringify({ output_path: outputPath }));
})();
